#include <iostream>

int cajas_para(int piezas) {
    const int piezas_por_caja{4};
    return (piezas + piezas_por_caja - 1) / piezas_por_caja;
}

bool intentar_cajas(int piezas, int& resultado) {
    if (piezas < 0 || piezas > 20) {
        return false;
    }
    resultado = cajas_para(piezas);
    return true;
}

void informar_rechazo_cajas(std::ostream& destino, int peticion, int piezas) {
    destino << "Erreur\n";
}

int main() {
    int piezas{0};
    int peticion{0};
    bool hubo_rechazos{false};
    while (std::cin >> piezas) {
        ++peticion;
        int cajas{77};
        if (intentar_cajas(piezas, cajas)) {
            std::cout << "Boîtes=" << cajas << "\n";
        } else {
            hubo_rechazos = true;
            informar_rechazo_cajas(std::cerr, peticion, piezas);
        }
    }
    return hubo_rechazos ? 1 : 0;
}

